batch["10292"] = "דורין הנדיב בנה את טאחונת העולם במשך עשרות שנים. הוא חזה עתיד שבו סוורטלפהיים תהיה שופעת וירוקה כמו השדות המיוערים ביותר בפאנהיים, וטאחונת העולם הייתה הצעד הראשון לקראת העתיד הזה. הוא נהג למכור אדמה פורייה ואיכותית לגמדים אחרים והשקיע את כל ההכנסות בשמירה על פעילות הטאחונה.\\n\\pכשאודין שמע על המכונה המופלאה הזו — ועל העצמאות שהיא עשויה להעניק יום אחד לסוורטלפהיים — הוא הציע לדורין זהב ללא גבול כדי להשמיד אותה. דורין סירב.\\n\\pאודין רצה למוטט את המבנה כולו, כמובן, אך שכנעתי אותו להמתין. במקום זאת, אסגארד פשוט בנתה טאחונת עולם משלה. מכרנו אדמה משלנו לגמדים במחירים שדורין לא יכול היה להתחרות בהם. הוא לא יכול היה להרשות לעצמו את תחזוקת המכונה המופלאה שלו, וכך היא הוזנחה.\\n\\pברגע שטאחונת העולם של דורין התקלקלה, אודין השמיד גם את זו של אסגארד. \\n\\nדורין שם קץ לחייו זמן קצר לאחר מכן.\\n\\nוזהו סיפורה של הדרך שבה סוורטלפהיים כמעט זכתה בעצמאות."
batch["10294"] = "הסיפור של הוניר אינו סיפור שמח במיוחד, אני חושש.\\n\\pאתה מבין, כאשר היחסים בין האיסיר לפאניר היו במצב בריא יחסית, הוצע חילופי תרבות. הפאניר ישלחו אחד משלהם לאסגארד, והאיסיר יעשו את אותו הדבר עבור פאנהיים.\\n\\pהפאניר שלחו נפח נשק צעיר וטוב לב בשם סטורלה להתגורר באסגארד.\\n\\pהאיסיר שלחו את הוניר.\\n\\pבחור טוב לב; תמים ומתוק. אבל טיפש כמו ערמת אבנים, הוא היה. לאחר ימים ספורים — וההבנה שהוניר זקוק לטיפול מתמיד כדי למנוע ממנו לפגוע בעצמו בטעות — התברר לפאניר שאודין רק שלח את הוניר כדרך מהירה להיפטר ממנו.\\n\\pובכל זאת, לפאניר לא היה אכפת. המשפחות השונות התאחדו כולן כדי לטפל בו — ואף הגדילו לעשות ועיצבו עבורו סמל משפחתי משלו.\\n\\nאך יום אחד, אחד המטפלים של הילד הזכיר בטעות את סלידתו הברורה של אודין מהילד, כשהם האמינו שהם מחוץ לטווח שמיעה.\\n\\pכל הזמן הזה, הוניר האמין שאודין יחזור יום אחד בשבילו: שהוא פשוט בחופשה נעימה עם חבריו הקסומים של הכול-אב.\\n\\pהם מצאו את גופתו למחרת בבוקר. עוד קורבן לאכזריותו של אודין."
batch["10300"] = "סמל המציג את חותם המשפחה של פריה ופרייר. של ניורד וסקאדי. משפחה שאיפיינה פעם כל דבר נאצל וחכם בפאניר, ובפאנהיים עצמה.\\n\\nואז אודין הרס את כל זה, לא?\\n\\nהתחתן עם פריה, ואז כלא אותה במידגארד.\\n\\pשיקר לאלה שאהבו אותה וגרם להם להאמין שהיא נטשה אותם. ואז המנוול ניהל מלחמה איטית ואכזרית באותם אנשים ממש שהוא נשבע לעשות עמם צדק.\\n\\pכשמודעים לכך, אולי אין זה מפתיע שהסמל הזה מושחת. כשפאניר רבים חושבים על פריה, הם חושבים רק על כאב.\\n\\nאדם מקווה שנוכל לשנות את כל זה."
batch["10302"] = "אח, קוואסיר. השיכור האגדי.\\n\\pהסיפורים מתארים אותו כחכם מאין כמוהו. ממציא השירה, הם אומרים! כשהוא מת, חבריו ערבבו את דמו עם דבש כדי ליצור את תמד השירה, שנאמר עליו שהוא מעניק לכל השותה אותו את כוחה של חוכמה שירית!\\n\\nהכל שטויות, כמובן.\\n\\nקוואסיר היה נהדר בדבר אחד, ודבר אחד בלבד: שתיית אלכוהול בכמויות. בלי להמעיט בערכו כלל — רובנו יכולים רק לקוות להיות טובים במשהו כפי שקוואסיר היה טוב בלהחזיק את המשקה שלו. אבל ה\"שירה\" שלו לבשה לעיתים קרובות צורה של ניבולי פה שהפכו ליצירתיים יותר ויותר, ואלו ששתו את דמו חשו \"השראה\" רק בגלל שנוזלי השיכור היו לפחות חמישים אחוזים אלכוהול עד שהתמוטט סוף סוף.\\n\\pאבל הוא היה איש באמת מצחיק. הוא ידע דבר או שניים על כפל משמעות."
batch["10312"] = "נבל מיניאטורי. לא ניתן לניגון, כמובן.\\n\\pסביר להניח שנועד לשקף את כישרונו המוזיקלי של פרייר. נאמר שעם כלי מיתר בידו ושיר על שפתיו, לא היה דבר שלא יכול היה להשיג. אף בתולה לא הייתה חסודה מדי, אף לוחם לא היה זועם מדי.\\n\\pהייתי רוצה לדמיין שפרייר היה מספיק חכם כדי לא לפנות לשירה וריקודים כשזה הגיע לתיווך שלום בין האלפים.\\n\\nזה מה שהייתי רוצה לדמיין, בכל אופן."
